#import "KARPAInterface.h"
#import "KARPARuntimeDumper.h"
#import "KARPAZipExporter.h"
@interface KARPAInterfaceViewController ()
@property(nonatomic,strong) UILabel *status; @property(nonatomic,strong) UIProgressView *progress; @property(nonatomic,strong) NSString *directory; @property(nonatomic) BOOL cancelled;
@end
@implementation KARPAInterfaceViewController
- (void)viewDidLoad{[super viewDidLoad];self.view.backgroundColor=UIColor.systemBackgroundColor;self.title=@"KARPA Runtime Dumper";UIStackView *s=[[UIStackView alloc]initWithFrame:CGRectZero];s.axis=UILayoutConstraintAxisVertical;s.spacing=12;s.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:s];[NSLayoutConstraint activateConstraints:@[[s.leadingAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.leadingAnchor constant:20],[s.trailingAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.trailingAnchor constant:-20],[s.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor constant:20]]];self.status=[UILabel new];self.status.text=@"Pronto — coleta explícita, somente leitura";self.status.numberOfLines=0;self.progress=[UIProgressView new];[s addArrangedSubview:self.status];[s addArrangedSubview:self.progress];[s addArrangedSubview:[self button:@"Full Runtime Dump" action:@selector(fullDump:)]];[s addArrangedSubview:[self button:@"Media Investigation" action:@selector(mediaDump:)]];[s addArrangedSubview:[self button:@"Export Reports" action:@selector(share:)]];[s addArrangedSubview:[self button:@"Cancel" action:@selector(cancel:)]];}
- (UIButton *)button:(NSString *)title action:(SEL)sel{UIButton *b=[UIButton buttonWithType:UIButtonTypeSystem];[b setTitle:title forState:UIControlStateNormal];[b addTarget:self action:sel forControlEvents:UIControlEventTouchUpInside];return b;}
- (void)collect:(BOOL)media{self.cancelled=NO;self.progress.progress=0;self.status.text=@"Coletando…";NSString *d=[NSSearchPathForDirectoriesInDomains(NSDocumentDirectory,NSUserDomainMask,YES).firstObject stringByAppendingPathComponent:@"KARPA_DUMPS"];self.directory=d;dispatch_async(dispatch_get_global_queue(QOS_CLASS_UTILITY,0),^{KARPAOptions *o=[KARPAOptions defaultOptions];o.mediaOnly=media;NSError *e=nil;BOOL ok=KARPACollectToDirectory(o,d,&e);dispatch_async(dispatch_get_main_queue(),^{self.progress.progress=1;self.status.text=ok? [NSString stringWithFormat:@"Concluído: %@",d]:[NSString stringWithFormat:@"Falha: %@",e];});});}
- (void)fullDump:(id)sender{[self collect:NO];} - (void)mediaDump:(id)sender{[self collect:YES];} - (void)cancel:(id)sender{self.cancelled=YES;self.status.text=@"Cancelamento solicitado; coleta síncrona atual terminará no próximo ponto seguro.";} - (void)share:(id)sender{if(!self.directory)return;NSString *zip=[self.directory stringByAppendingPathComponent:@"KARPA_DUMPS.zip"];NSError *e=nil;if(!KARPAWriteZIPForDirectory(self.directory,zip,&e)){self.status.text=[NSString stringWithFormat:@"ZIP falhou: %@",e];return;}UIActivityViewController *a=[[UIActivityViewController alloc]initWithActivityItems:@[[NSURL fileURLWithPath:zip]] applicationActivities:nil];[self presentViewController:a animated:YES completion:nil];}
@end
